// Generates src/protocol/paged.gen.ts and legacyMap.gen.ts from the firmware's
// paged command registry and legacy opcode map, vendored byte-for-byte in src/protocol/vendor/ at the commit named
// in SOURCE.json.
//
// Usage:
//   node scripts/gen-paged.mjs              regenerate from the vendored files
//   node scripts/gen-paged.mjs --check      exit 1 if a generated file is stale
//   node scripts/gen-paged.mjs --fetch SHA  re-vendor from WeebLabs/DSPi at SHA, then regenerate

import { readFileSync, writeFileSync } from 'node:fs';
import { resolve, dirname } from 'node:path';
import { fileURLToPath } from 'node:url';

const ROOT = resolve(dirname(fileURLToPath(import.meta.url)), '..');
const VENDOR = resolve(ROOT, 'src/protocol/vendor');
const OUT = resolve(ROOT, 'src/protocol/paged.gen.ts');
const OUT_LEGACY = resolve(ROOT, 'src/protocol/legacyMap.gen.ts');
const REPO = 'WeebLabs/DSPi';
const FILES = ['dspi_commands.json', 'legacy_map.json'];

function fail(msg) {
  console.error(`gen-paged: ${msg}`);
  process.exit(1);
}

// Downloads and validates both files before writing any, so a failed fetch
// leaves the vendored set untouched.
async function vendor(sha) {
  if (!/^[0-9a-f]{40}$/.test(sha)) fail('--fetch needs a full 40-character commit SHA');
  const bodies = [];
  for (const file of FILES) {
    const url = `https://raw.githubusercontent.com/${REPO}/${sha}/Documentation/protocol/${file}`;
    const res = await fetch(url);
    if (!res.ok) fail(`${url}: HTTP ${res.status}`);
    bodies.push(Buffer.from(await res.arrayBuffer()));
  }
  const [registry, legacy] = bodies.map((b, i) => {
    try { return JSON.parse(b.toString('utf8')); } catch (err) { return fail(`${FILES[i]}: ${err.message}`); }
  });
  validate(registry, legacy);
  FILES.forEach((file, i) => writeFileSync(resolve(VENDOR, file), bodies[i]));
  const source = { repo: REPO, sha, path: 'Documentation/protocol', files: FILES };
  writeFileSync(resolve(VENDOR, 'SOURCE.json'), `${JSON.stringify(source, null, 2)}\n`);
}

const hex = (n, width) => `0x${n.toString(16).toUpperCase().padStart(width, '0')}`;
const str = (s) => {
  if (!/^[\w.+:-]*$/.test(s)) fail(`unexpected characters in token ${JSON.stringify(s)}`);
  return `'${s}'`;
};
const docComment = (s, indent) => (s ? `${indent}/** ${s.replace(/\*\//g, '* /')} */\n` : '');

const IDENT = /^[A-Z_][A-Z0-9_]*$/;

function validate(registry, legacy) {
  const seen = new Set();
  for (const page of registry.pages) {
    if (!IDENT.test(page.mnemonic)) fail(`page mnemonic ${JSON.stringify(page.mnemonic)} is not an identifier`);
    if (!(page.page >= 1 && page.page <= 0xFF)) fail(`page ${page.mnemonic}: number ${page.page} is outside 1..255`);
    if (legacy.pages[page.mnemonic] !== page.page) fail(`page ${page.mnemonic} differs between the registry and legacy_map`);
    for (const c of page.commands) {
      if (!IDENT.test(c.name)) fail(`${page.mnemonic}: command name ${JSON.stringify(c.name)} is not an identifier`);
      if (!(c.cmd >= 0 && c.cmd <= 0xFF)) fail(`${page.mnemonic}.${c.name}: cmd ${c.cmd} is outside 0..255`);
      if (!c.get && !c.set) fail(`${page.mnemonic}.${c.name}: neither GET nor SET`);
      if (c.id !== ((page.page << 8) | c.cmd)) fail(`${page.mnemonic}.${c.name}: id ${c.id} is not page << 8 | cmd`);
      if (seen.has(c.id)) fail(`duplicate command id ${hex(c.id, 4)}`);
      seen.add(c.id);
    }
  }
}

function render(registry, legacy, source) {
  const commands = registry.pages.flatMap((p) => p.commands);
  const addrs = [...new Set(commands.map((c) => c.addr))].sort();
  const flags = [...new Set(commands.flatMap((c) => c.flags))].sort();
  const union = (xs) => (xs.length ? xs.map(str).join(' | ') : 'never');

  let out = '';
  out += `// Generated by scripts/gen-paged.mjs from ${source.repo} ${source.path}\n`;
  out += `// at ${source.sha}. Do not edit; run \`npm run gen:paged\`.\n\n`;
  out += `export const PROTOCOL_MAJOR = ${registry.protocol.major};\n`;
  out += `export const PROTOCOL_MINOR = ${registry.protocol.minor};\n\n`;
  out += `export type PagedAddr = ${union(addrs)};\n\n`;
  out += `export type PagedFlag = ${union(flags)};\n\n`;
  out += `export interface PagedCommand {\n`;
  out += `  readonly id: number;\n`;
  out += `  readonly get: boolean;\n`;
  out += `  readonly set: boolean;\n`;
  out += `  readonly addr: PagedAddr;\n`;
  out += `  // GET reply bytes; 'var' when variable, null when there is no GET.\n`;
  out += `  readonly getLen: number | 'var' | null;\n`;
  out += `  // SET payload bounds; null for BULK commands, whose payload is the whole struct.\n`;
  out += `  readonly setMin: number | null;\n`;
  out += `  readonly setMax: number | null;\n`;
  out += `  readonly flags: readonly PagedFlag[];\n`;
  out += `  // Firmware build condition; null when always built.\n`;
  out += `  readonly build: string | null;\n`;
  out += `}\n\n`;

  out += `// Result codes SYS.LAST_RESULT reports.\n`;
  out += `export const VcResult = {\n`;
  for (const [name, code] of Object.entries(legacy.vc_results)) out += `  ${name}: ${hex(code, 2)},\n`;
  out += `} as const;\n\n`;

  out += `export const PagedPage = {\n`;
  for (const p of registry.pages) {
    out += docComment(p.doc, '  ');
    out += `  ${p.mnemonic}: { page: ${hex(p.page, 2)}, revision: ${p.revision} },\n`;
  }
  out += `} as const;\n\n`;

  out += `export const PagedCmd = {\n`;
  for (const p of registry.pages) {
    out += `  ${p.mnemonic}: {\n`;
    for (const c of p.commands) {
      const getLen = c.get_len === null ? 'null' : typeof c.get_len === 'number' ? String(c.get_len) : str(c.get_len);
      const bulk = c.flags.includes('BULK');
      const fields = [
        `id: ${hex(c.id, 4)}`,
        `get: ${c.get}`,
        `set: ${c.set}`,
        `addr: ${str(c.addr)}`,
        `getLen: ${getLen}`,
        `setMin: ${bulk ? 'null' : c.set_min}`,
        `setMax: ${bulk ? 'null' : c.set_max}`,
        `flags: [${c.flags.map(str).join(', ')}]`,
        `build: ${c.build === null ? 'null' : str(c.build)}`,
      ];
      out += docComment(c.doc, '    ');
      out += `    ${c.name}: { ${fields.join(', ')} },\n`;
    }
    out += `  },\n`;
  }
  out += `} as const satisfies Record<keyof typeof PagedPage, Record<string, PagedCommand>>;\n`;
  return out;
}

// Object-literal emitter: single-quoted strings, bare identifier keys, input
// key order, so output is deterministic.
function lit(v) {
  if (v === null) return 'null';
  if (typeof v === 'number' || typeof v === 'boolean') return String(v);
  if (typeof v === 'string') return str(v);
  if (Array.isArray(v)) return `[${v.map(lit).join(', ')}]`;
  const entries = Object.entries(v).map(([k, x]) => `${/^([A-Za-z_]\w*|\d+)$/.test(k) ? k : str(k)}: ${lit(x)}`);
  return entries.length ? `{ ${entries.join(', ')} }` : '{}';
}

function renderLegacy(registry, legacy, source) {
  const ids = new Map();
  for (const p of registry.pages) for (const c of p.commands) ids.set(`${p.mnemonic}.${c.name}`, c.id);
  const target = (name, where) => {
    const id = ids.get(name);
    if (id === undefined) fail(`${where}: target ${JSON.stringify(name)} is not in the registry`);
    return id;
  };
  const vc = (name, where) => {
    const code = legacy.vc_results[name];
    if (code === undefined) fail(`${where}: unknown result ${JSON.stringify(name)}`);
    return code;
  };
  // Ordered [result code, byte] pairs, in legacy_map order: inversion takes the first match.
  const byVc = (m, where) => Object.entries(m).map(([k, v]) => [vc(k, where), v]);

  const adapter = (a, where) => {
    if (a === null || a === undefined) return null;
    if (a.kind === 'custom') return { kind: 'custom' };
    const o = { kind: a.kind };
    if (a.kind === 'split') {
      o.selector = a.selector;
      o.cases = Object.fromEntries(Object.entries(a.cases).map(([k, c]) => [k, adapter(c, `${where}[${k}]`)]));
      o.default = adapter(a.default, `${where}[default]`);
      return o;
    }
    o.target = target(a.target, where);
    if (a.addr) o.addr = 'const' in a.addr ? a.addr : { shift: a.addr.shift, mask: a.addr.mask, add: a.addr.add ?? 0 };
    if (a.value) o.value = a.value;
    for (const k of ['status', 'trunc']) if (a[k] !== undefined) o[k] = a[k];
    if (a.status_overrides) o.status_overrides = byVc(a.status_overrides, where);
    return o;
  };

  const families = Object.fromEntries(Object.entries(legacy.status_families).map(([name, f]) => [
    name,
    { success: f.success, fromVc: byVc(f.from_vc, `status family ${name}`) },
  ]));

  const ops = Object.entries(legacy.opcodes).map(([name, op]) => {
    const o = { code: op.code };
    if (op.in) o.in = adapter(op.in, `${name}.in`);
    if (op.out) o.out = adapter(op.out, `${name}.out`);
    return o;
  });

  let out = '';
  out += `// Generated by scripts/gen-paged.mjs from ${source.repo} ${source.path}\n`;
  out += `// at ${source.sha}. Do not edit; run \`npm run gen:paged\`.\n\n`;
  out += `export type LegacyAddr = { const: number } | { shift: number; mask: number; add: number };\n`;
  out += `export interface LegacyField { shift: number; mask: number }\n`;
  out += `export type LegacyStatusFamily = ${Object.keys(families).map(str).join(' | ')};\n`;
  out += `export type VcByte = [vc: number, byte: number];\n\n`;
  out += `export type LegacyAdapter =\n`;
  out += `  | { kind: 'direct'; target: number; addr?: LegacyAddr; trunc?: number }\n`;
  out += `  | { kind: 'act_value'; target: number; addr?: LegacyAddr; value: LegacyField; status: LegacyStatusFamily; status_overrides?: VcByte[] }\n`;
  out += `  | { kind: 'act_addr'; target: number; addr?: LegacyAddr; status: LegacyStatusFamily; status_overrides?: VcByte[] }\n`;
  out += `  | { kind: 'act_packed'; target: number; addr: LegacyAddr; value: LegacyField; status: LegacyStatusFamily; status_overrides?: VcByte[] }\n`;
  out += `  | { kind: 'split'; selector: LegacyField; cases: Record<number, LegacyAdapter | null>; default: LegacyAdapter | null }\n`;
  out += `  | { kind: 'custom' };\n\n`;
  out += `export interface LegacyOpcode {\n  code: number;\n  in?: LegacyAdapter | null;\n  out?: LegacyAdapter | null;\n}\n\n`;
  out += `// 1.1.6 write-as-read status bytes: the success byte and the byte each refusal result maps to, first match wins.\n`;
  out += `export const StatusFamily: Record<LegacyStatusFamily, { success: number; fromVc: VcByte[] }> = {\n`;
  for (const [name, f] of Object.entries(families)) out += `  ${name}: ${lit(f)},\n`;
  out += `};\n\n`;
  out += `export const LEGACY_ADAPTERS: readonly LegacyOpcode[] = [\n`;
  for (const o of ops) out += `  ${lit(o)},\n`;
  out += `];\n`;
  return out;
}

const args = process.argv.slice(2);
const mode = args[0] ?? 'generate';
if (!['generate', '--check', '--fetch'].includes(mode) || args.length > (mode === '--fetch' ? 2 : 1)) {
  fail(`unknown arguments: ${args.join(' ')} (expected none, --check, or --fetch SHA)`);
}
if (mode === '--fetch') await vendor(args[1] ?? '');

const read = (file) => JSON.parse(readFileSync(resolve(VENDOR, file), 'utf8'));
const registry = read('dspi_commands.json');
const legacy = read('legacy_map.json');
validate(registry, legacy);
const source = read('SOURCE.json');
const text = render(registry, legacy, source);
const legacyText = renderLegacy(registry, legacy, source);

if (mode === '--check') {
  for (const [file, expected] of [[OUT, text], [OUT_LEGACY, legacyText]]) {
    let current = '';
    try { current = readFileSync(file, 'utf8').replace(/\r\n/g, '\n'); } catch { /* missing counts as stale */ }
    if (current !== expected) fail(`${file.slice(ROOT.length + 1)} is stale; run \`npm run gen:paged\``);
  }
  console.log('gen-paged: generated files are current');
} else {
  writeFileSync(OUT, text);
  writeFileSync(OUT_LEGACY, legacyText);
  const count = registry.pages.reduce((n, p) => n + p.commands.length, 0);
  console.log(`gen-paged: wrote ${count} commands on ${registry.pages.length} pages`);
}
